        if (new_rows != rows || new_cols != cols) {
            rows = new_rows;
            cols = new_cols;
            // Realloc columns array
            free(columns);
            columns = calloc(cols > 0 ? cols : 1, sizeof(Column));
            for (int i=0;i<cols;i++) {
