                columns[i].length = (rand() % (rows/2)) + (rows/3);
                if (columns[i].length < 5) columns[i].length = 5;
                columns[i].speed = (rand() % 3) + 1;
                columns[i].spaces = rand() % 5;
            }
            clear();
        }
    }

    free(columns);
    endwin();
    if (screen) delscreen(screen);
    if (tty_fp) fclose(tty_fp);
    return 0;
