        case COLOR_WHITE_IDX: matrix_color_pair = 4; break;
        case COLOR_YELLOW_IDX: matrix_color_pair = 5; break;
        case COLOR_CYAN_IDX: matrix_color_pair = 6; break;
        case COLOR_MAGENTA_IDX: matrix_color_pair = 7; break;
        case COLOR_BLACK_IDX: matrix_color_pair = 8; break;
