                        break;
                    case 'B':
                        current_bold = 2;
                        break;
                    case 'n':
                    case 'N':
                        current_bold = 0;
                        break;
                    case '0': case '1': case '2': case '3': case '4':
                    case '5': case '6': case '7': case '8': case '9':
                        current_delay = ch - '0';
                        break;
                    case '!':
                        current_color_pair = 2;
                        break;
                    case '@':
                        current_color_pair = 1;
                        break;
                    case '#':
                        current_color_pair = 5;
                        break;
                    case '$':
                        current_color_pair = 3;
                        break;
                    case '%':
                        current_color_pair = 7;
                        break;
                    case '^':
                        current_color_pair = 6;
                        break;
                    case '&':
                        current_color_pair = 4;
                        break;
                    case ')':
                        current_color_pair = 8;
                        break;
                    default:
                        break;
                }
            }
        }

