                columns[c].counter = 0;
            }
            int y = columns[c].y;
            int len = columns[c].length;

            if (y >=0 && y < rows) {
                char ch_char;
                if (lambda_mode) {
                    ch_char = 'L';
                } else if (japanese) {
                    ch_char = (char)(33 + rand() % 94);
                } else {
                    ch_char = (char)(33 + rand() % 94);
                }
                int attr = 0;
                if (rainbow) {
                    int rp = (rand() % 7) + 1;
                    attr = COLOR_PAIR(rp);
                } else {
                    attr = COLOR_PAIR(current_color_pair);
                }
                if (current_bold == 2) {
                    attr |= A_BOLD;
                } else if (current_bold == 1) {
                    if (rand() % 2) attr |= A_BOLD;
                }
                move(y, c);
                attron(attr);
                addch(ch_char);
                attroff(attr);
            }

            int tail_y = y - len - columns[c].spaces;
            if (tail_y >=0 && tail_y < rows) {
                move(tail_y, c);
                addch(' ');
            }

