                        char rc = (char)(33 + rand() % 94);
                        move(ry, c);
                        int attr = 0;
                        if (rainbow) {
                            int rp = (rand() % 7) + 1;
                            attr = COLOR_PAIR(rp);
                        } else {
                            attr = COLOR_PAIR(current_color_pair);
                        }
                        if (current_bold == 2) attr |= A_BOLD;
                        else if (current_bold == 1 && (rand()%2)) attr |= A_BOLD;
                        attron(attr);
